/// gridSpec (by ecCodes) of every message of a file
std::vector<std::string> gridspecs(const std::string& path) {
    std::unique_ptr<FILE, decltype(&std::fclose)> file(std::fopen(path.c_str(), "r"), &std::fclose);
    ASSERT(file);

    std::vector<std::string> specs;

    int err = 0;
    while (auto* h = codes_handle_new_from_file(nullptr, file.get(), PRODUCT_GRIB, &err)) {
        std::unique_ptr<codes_handle, decltype(&codes_handle_delete)> handle(h, &codes_handle_delete);

        size_t length = 0;
        GRIB_CALL(codes_get_length(h, "gridSpec", &length));

        std::string spec(length, '\0');
        GRIB_CALL(codes_get_string(h, "gridSpec", spec.data(), &length));
        spec.resize(length);

        specs.push_back(spec);
    }

    ASSERT(err == CODES_SUCCESS);
    return specs;
}


